## Context\nThe middleware processes all incoming requests.\n\n## Problem Statement\nThe default exported function lacks an explicit `NextResponse` return type, bypassing strict TS compile checks.\n\n## Proposed Solution\nType the middleware correctly as `NextMiddleware`.\n\n## Technical Details\n- **Target File:** `middleware.ts`\n- The middleware processes all incoming requests. The default exported function lacks an explicit `NextResponse` return type, bypassing strict TS compile checks.\n\n```typescript\nimport { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { rateLimit } from './lib/rate-limit';

/**
 * Middleware to enforce rate limiting on specific API routes.
 *
 * Protected Routes:
 * - /api/streak
 * - /api/github
 * - /api/track-user
 * - /api/stats
 * - /api/og
 *
 * Limit: 60 requests per minute per IP.
 */
export async function middleware(request: NextRequest) {
  // Use Vercel's ip property if available, fallback to headers, then localhost
  const ip =
    request.headers.get('x-forwarded-for')?.split(',')[0] ??
    request.headers.get('x-real-ip') ??
    '127.0.0.1';

  // Apply rate limiting
  // 60 requests per 60,000ms (1 minute)
  const result = await rateLimit(ip, 60, 60000);

  if (!result.success) {
    return NextResponse.json(
      { error: 'Too many requests' },
      {
        status: 429,
        headers: {
          'Content-Type': 'application/json',
          'X-RateLimit-Limit': result.limit.toString(),
          'X-RateLimit-Remaining': result.remaining.toString(),
          'X-RateLimit-Reset': result.reset.toString(),
        },
      }
    );
  }

  // Add rate limit headers to the response for successful requests
  const response = NextResponse.next();
  response.headers.set('X-RateLimit-Limit', result.limit.toString());
  response.headers.set('X-RateLimit-Remaining', result.remaining.toString());
  response.headers.set('X-RateLimit-Reset', result.reset.toString());

  return response;
}

/**
 * Configure which routes should trigger this middleware.
 * Using a matcher is more efficient than checking pathnames inside the middleware.
 */
export const config = {
  matcher: [
    '/api/streak/:path*',
    '/api/github/:path*',
    '/api/track-user/:path*',
    '/api/stats/:path*',
    '/api/og/:path*',
  ],
};
\n```\n\n## Acceptance Criteria\n- The component displays a clear visual indicator of the change (hover state, transition, or updated styling).\n- The core behavior works as expected: type the middleware correctly as `nextmiddleware`.\n- All existing tests pass and 'npm run typecheck' and 'npm run lint' produce no errors.

