## Context\nThe middleware relies on IP addresses for rate limiting.\n\n## Problem Statement\nIf the app is deployed behind custom proxies, `X-Forwarded-For` might be blindly trusted, allowing IP spoofing.\n\n## Proposed Solution\nConfigure Next.js trusted proxies explicitly or use an authoritative header like `x-real-ip`.\n\n## Technical Details\n- **Target File:** `middleware.ts`\n- The middleware relies on IP addresses for rate limiting. If the app is deployed behind custom proxies, `X-Forwarded-For` might be blindly trusted, allowing IP spoofing.\n\n```typescript\nimport { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { rateLimit } from './lib/rate-limit';

/**
 * Middleware to enforce rate limiting on specific API routes.
 *
 * Protected Routes:
 * - /api/streak
 * - /api/github
 * - /api/track-user
 *
 * Limit: 60 requests per minute per IP.
 */
export function middleware(request: NextRequest) {
  // Use Vercel's ip property if available, fallback to headers, then localhost
  const ip =
    request.headers.get('x-forwarded-for')?.split(',')[0] ??
    request.headers.get('x-real-ip') ??
    '127.0.0.1';

  // Apply rate limiting
  // 60 requests per 60,000ms (1 minute)
  const result = rateLimit(ip, 60, 60000);

  if (!result.success) {
    return NextResponse.json(
      { error: 'Too many requests' },
      {
        status: 429,
        headers: {
          'Content-Type': 'application/json',
          'X-RateLimit-Limit': result.limit.toString(),
          'X-RateLimit-Remaining': result.remaining.toString(),
          'X-RateLimit-Reset': result.reset.toString(),
        },
      }
    );
  }

  // Add rate limit headers to the response for successful requests
  const response = NextResponse.next();
  response.headers.set('X-RateLimit-Limit', result.limit.toString());
  response.headers.set('X-RateLimit-Remaining', result.remaining.toString());
  response.headers.set('X-RateLimit-Reset', result.reset.toString());

  return response;
}

/**
 * Configure which routes should trigger this middleware.
 * Using a matcher is more efficient than checking pathnames inside the middleware.
 */
export const config = {
